package lf.sandbox.time.reminder;

import java.time.LocalTime;
import java.time.temporal.ChronoUnit;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Optional;
import org.springframework.stereotype.Repository;

@Repository
public class InMemoryReminderRepository implements ReminderRepository {

    private static final int MAX_TEXT_LENGTH = 140;

    private final List<Reminder> reminders = new ArrayList<>();
    private long nextId = 1;

    public InMemoryReminderRepository() {}

    private static String validatedText(String text) {
        if (text == null) {
            throw new IllegalArgumentException("text must not be null");
        }
        String stripped = text.strip();
        if (stripped.isEmpty() || stripped.length() > MAX_TEXT_LENGTH) {
            throw new IllegalArgumentException("text must have 1 to 140 characters");
        }
        return stripped;
    }

    private static LocalTime validatedTime(LocalTime at) {
        if (at == null) {
            throw new IllegalArgumentException("at must not be null");
        }
        return at.truncatedTo(ChronoUnit.SECONDS);
    }

    private boolean duplicates(long excludedId, String text, LocalTime at) {
        String key = text.toLowerCase(Locale.ROOT);
        for (Reminder existing : reminders) {
            if (existing.id() != excludedId
                    && existing.at().equals(at)
                    && existing.text().toLowerCase(Locale.ROOT).equals(key)) {
                return true;
            }
        }
        return false;
    }

    @Override
    public synchronized Reminder save(String text, LocalTime at) {
        String normalizedText = validatedText(text);
        LocalTime normalizedTime = validatedTime(at);
        if (duplicates(-1, normalizedText, normalizedTime)) {
            throw new IllegalStateException("duplicate reminder");
        }
        Reminder reminder = new Reminder(nextId, normalizedText, normalizedTime);
        reminders.add(reminder);
        nextId++;
        return reminder;
    }

    @Override
    public synchronized Optional<Reminder> update(long id, String text, LocalTime at) {
        String normalizedText = validatedText(text);
        LocalTime normalizedTime = validatedTime(at);
        for (int i = 0; i < reminders.size(); i++) {
            Reminder existing = reminders.get(i);
            if (existing.id() == id) {
                if (duplicates(id, normalizedText, normalizedTime)) {
                    throw new IllegalStateException("duplicate reminder");
                }
                Reminder updated = new Reminder(id, normalizedText, normalizedTime);
                reminders.set(i, updated);
                return Optional.of(updated);
            }
        }
        return Optional.empty();
    }

    @Override
    public synchronized Optional<Reminder> snooze(long id, int minutes) {
        if (minutes < 1 || minutes > 1440) {
            throw new IllegalArgumentException("minutes must be between 1 and 1440");
        }
        for (int i = 0; i < reminders.size(); i++) {
            Reminder existing = reminders.get(i);
            if (existing.id() == id) {
                LocalTime newTime = existing.at().plusMinutes(minutes);
                if (duplicates(id, existing.text(), newTime)) {
                    throw new IllegalStateException("duplicate reminder");
                }
                Reminder updated = new Reminder(id, existing.text(), newTime);
                reminders.set(i, updated);
                return Optional.of(updated);
            }
        }
        return Optional.empty();
    }

    @Override
    public synchronized List<Reminder> findAll() {
        return List.copyOf(reminders);
    }

    @Override
    public synchronized Optional<Reminder> findById(long id) {
        for (Reminder reminder : reminders) {
            if (reminder.id() == id) {
                return Optional.of(reminder);
            }
        }
        return Optional.empty();
    }

    @Override
    public synchronized boolean deleteById(long id) {
        return reminders.removeIf(r -> r.id() == id);
    }

    @Override
    public synchronized List<Reminder> findByTextContaining(String query) {
        if (query == null) {
            throw new IllegalArgumentException("query must not be null");
        }
        String needle = query.strip().toLowerCase(Locale.ROOT);
        List<Reminder> result = new ArrayList<>();
        for (Reminder reminder : reminders) {
            if (reminder.text().toLowerCase(Locale.ROOT).contains(needle)) {
                result.add(reminder);
            }
        }
        return List.copyOf(result);
    }
}

package lf.sandbox.time.reminder;

import java.time.LocalTime;

public record Reminder(long id, String text, LocalTime at) {}

package lf.sandbox.time.reminder;

import java.net.URI;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.time.format.ResolverStyle;
import java.util.List;
import java.util.Map;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestMethod;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ReminderController {

    private static final DateTimeFormatter TIME =
            DateTimeFormatter.ofPattern("HH:mm:ss").withResolverStyle(ResolverStyle.STRICT);

    private final ReminderRepository repository;

    public ReminderController(ReminderRepository repository) {
        this.repository = repository;
    }

    private static LocalTime validBodyTime(Map<String, Object> body) {
        if (body == null || !(body.get("text") instanceof String) || !(body.get("at") instanceof String at)) {
            throw new IllegalArgumentException("invalid reminder body");
        }
        try {
            return LocalTime.parse(at, TIME);
        } catch (DateTimeParseException e) {
            throw new IllegalArgumentException("invalid reminder time", e);
        }
    }

    @PostMapping("/api/reminders")
    public ResponseEntity<Object> create(@RequestBody(required = false) Map<String, Object> body) {
        final Reminder saved;
        try {
            LocalTime time = validBodyTime(body);
            saved = repository.save((String) body.get("text"), time);
        } catch (IllegalArgumentException e) {
            return ResponseEntity.badRequest().build();
        } catch (IllegalStateException e) {
            return ResponseEntity.status(409).build();
        }
        return ResponseEntity.created(URI.create("/api/reminders/" + saved.id()))
                .body(toResponse(saved));
    }

    @PutMapping("/api/reminders/{id}")
    public ResponseEntity<Object> update(
            @PathVariable String id, @RequestBody(required = false) Map<String, Object> body) {
        final long value;
        try {
            value = Long.parseLong(id);
        } catch (NumberFormatException e) {
            return ResponseEntity.badRequest().build();
        }
        try {
            LocalTime time = validBodyTime(body);
            return repository
                    .update(value, (String) body.get("text"), time)
                    .<ResponseEntity<Object>>map(r -> ResponseEntity.ok(toResponse(r)))
                    .orElseGet(() -> ResponseEntity.notFound().build());
        } catch (IllegalArgumentException e) {
            return ResponseEntity.badRequest().build();
        } catch (IllegalStateException e) {
            return ResponseEntity.status(409).build();
        }
    }

    @PostMapping("/api/reminders/{id}/snooze")
    public ResponseEntity<Object> snooze(
            @PathVariable String id, @RequestParam(name = "minutes", required = false) String minutes) {
        final long reminderId;
        final int amount;
        if (minutes == null || !minutes.matches("[0-9]+")) {
            return ResponseEntity.badRequest().build();
        }
        try {
            reminderId = Long.parseLong(id);
            amount = Integer.parseInt(minutes);
        } catch (NumberFormatException e) {
            return ResponseEntity.badRequest().build();
        }
        try {
            return repository
                    .snooze(reminderId, amount)
                    .<ResponseEntity<Object>>map(r -> ResponseEntity.ok(toResponse(r)))
                    .orElseGet(() -> ResponseEntity.notFound().build());
        } catch (IllegalArgumentException e) {
            return ResponseEntity.badRequest().build();
        } catch (IllegalStateException e) {
            return ResponseEntity.status(409).build();
        }
    }

    // A variable {id} PUT mapping would otherwise turn PUT /stats into 400.
    // Keep the existing statistics endpoint's method contract (REM-D3/E5).
    @RequestMapping(
            value = "/api/reminders/stats",
            method = {RequestMethod.PUT, RequestMethod.POST, RequestMethod.DELETE, RequestMethod.PATCH})
    public ResponseEntity<Void> statsMethodNotAllowed() {
        return ResponseEntity.status(405).build();
    }

    @GetMapping("/api/reminders")
    public List<ReminderResponse> list(@RequestParam(name = "q", required = false) String q) {
        List<Reminder> found = (q == null || q.isBlank()) ? repository.findAll() : repository.findByTextContaining(q);
        return found.stream().map(ReminderController::toResponse).toList();
    }

    @GetMapping("/api/reminders/{id}")
    public ResponseEntity<Object> get(@PathVariable String id) {
        long value;
        try {
            value = Long.parseLong(id);
        } catch (NumberFormatException e) {
            return ResponseEntity.badRequest().build();
        }
        return repository
                .findById(value)
                .<ResponseEntity<Object>>map(r -> ResponseEntity.ok(toResponse(r)))
                .orElseGet(() -> ResponseEntity.notFound().build());
    }

    @DeleteMapping("/api/reminders/{id}")
    public ResponseEntity<Void> delete(@PathVariable String id) {
        long value;
        try {
            value = Long.parseLong(id);
        } catch (NumberFormatException e) {
            return ResponseEntity.badRequest().build();
        }
        if (repository.deleteById(value)) {
            return ResponseEntity.noContent().build();
        }
        return ResponseEntity.notFound().build();
    }

    private static ReminderResponse toResponse(Reminder r) {
        return new ReminderResponse(r.id(), r.text(), r.at().format(TIME));
    }

    public record ReminderResponse(long id, String text, String at) {}
}

