package lf.sandbox.time.reminder;

import java.time.LocalTime;

public record ReminderStats(int total, LocalTime earliest, LocalTime latest, Reminder next, boolean nextIsTomorrow) {}

package lf.sandbox.time.reminder;

import java.time.Clock;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import java.util.LinkedHashMap;
import java.util.Map;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ReminderStatsController {

    private static final DateTimeFormatter TIME = DateTimeFormatter.ofPattern("HH:mm:ss");

    private final ReminderRepository repository;
    private final ReminderStatsService statsService;
    private final Clock clock;

    public ReminderStatsController(ReminderRepository repository, ReminderStatsService statsService, Clock clock) {
        this.repository = repository;
        this.statsService = statsService;
        this.clock = clock;
    }

    @GetMapping("/api/reminders/stats")
    public Map<String, Object> stats() {
        ReminderStats result = statsService.compute(repository.findAll(), LocalTime.now(clock));
        Map<String, Object> body = new LinkedHashMap<>();
        body.put("total", result.total());
        body.put("earliest", format(result.earliest()));
        body.put("latest", format(result.latest()));
        body.put("next", nextResponse(result.next()));
        body.put("nextIsTomorrow", result.nextIsTomorrow());
        return body;
    }

    private static String format(LocalTime time) {
        return time == null ? null : time.format(TIME);
    }

    private static Map<String, Object> nextResponse(Reminder reminder) {
        if (reminder == null) {
            return null;
        }
        Map<String, Object> next = new LinkedHashMap<>();
        next.put("id", reminder.id());
        next.put("text", reminder.text());
        next.put("at", format(reminder.at()));
        return next;
    }
}

package lf.sandbox.time.reminder;

import java.time.LocalTime;
import java.time.temporal.ChronoUnit;
import java.util.List;
import org.springframework.stereotype.Service;

@Service
public class ReminderStatsService {

    public ReminderStatsService() {}

    public ReminderStats compute(List<Reminder> reminders, LocalTime now) {
        if (reminders == null || now == null) {
            throw new IllegalArgumentException("reminders and now must not be null");
        }
        if (reminders.isEmpty()) {
            return new ReminderStats(0, null, null, null, false);
        }

        LocalTime reference = now.truncatedTo(ChronoUnit.SECONDS);
        LocalTime earliest = null;
        LocalTime latest = null;
        Reminder first = null;
        Reminder upcoming = null;

        for (Reminder reminder : reminders) {
            LocalTime at = reminder.at();
            if (earliest == null || at.isBefore(earliest)) {
                earliest = at;
            }
            if (latest == null || at.isAfter(latest)) {
                latest = at;
            }
            if (first == null || earlier(reminder, first)) {
                first = reminder;
            }
            if (!at.isBefore(reference) && (upcoming == null || earlier(reminder, upcoming))) {
                upcoming = reminder;
            }
        }

        boolean tomorrow = upcoming == null;
        return new ReminderStats(reminders.size(), earliest, latest, tomorrow ? first : upcoming, tomorrow);
    }

    private static boolean earlier(Reminder left, Reminder right) {
        int comparison = left.at().compareTo(right.at());
        return comparison < 0 || (comparison == 0 && left.id() < right.id());
    }
}

