/**
 * This protected visible test is staged in PR 2, after ex4a has passed.
 * The controller belongs exclusively to ex4b. Skip, rather than fail,
 * while the lot B controller class is absent from the real base commit.
 * It automatically executes when ex4b supplies ReminderController.
 */
@SpringBootTest
// Each test starts with an empty in-memory repository: no ordering between test classes.
@DirtiesContext(classMode = ClassMode.BEFORE_EACH_TEST_METHOD)
@AutoConfigureMockMvc
class ReminderControllerVisibleTest {

    @Autowired MockMvc mvc;

    @BeforeEach
    void requireLotBController() {
        boolean controllerExists;
        try {
            Class.forName("lf.sandbox.time.reminder.ReminderController");
            controllerExists = true;
        } catch (ClassNotFoundException e) {
            controllerExists = false;
        }
        Assumptions.assumeTrue(controllerExists, "REM-B controller is created by ex4b only");
    }

    @Test
    void postCreatedAndGetOrderedList() throws Exception {
        mvc.perform(post("/api/reminders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"text\":\"  take a break  \",\"at\":\"13:20:30\"}"))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", org.hamcrest.Matchers.matchesPattern("/api/reminders/\\d+")))
                .andExpect(jsonPath("$.text").value("take a break"))
                .andExpect(jsonPath("$.at").value("13:20:30"))
                // P4: responses may also carry priority; accept both shapes.
                .andExpect(jsonPath("$.*", anyOf(hasSize(3), hasSize(4))));

        mvc.perform(get("/api/reminders"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$", org.hamcrest.Matchers.hasSize(org.hamcrest.Matchers.greaterThanOrEqualTo(1))))
                .andExpect(jsonPath("$[0].text").value("take a break"));
    }

    @Test
    void invalidPostReturnsBadRequest() throws Exception {
        mvc.perform(post("/api/reminders")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"at\":\"13:20:30\"}"))
                .andExpect(status().isBadRequest());
    }
}

package lf.sandbox.time.reminder;

import static org.assertj.core.api.Assertions.assertThat;

import java.lang.reflect.Method;
import java.time.LocalTime;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

class ReminderRepositoryDeleteSearchVisibleTest {
    @BeforeEach
    void requiresLotCMethods() {
        try {
            ReminderRepository.class.getMethod("deleteById", long.class);
            ReminderRepository.class.getMethod("findByTextContaining", String.class);
        } catch (NoSuchMethodException e) {
            Assumptions.assumeTrue(false, "REM-C methods only exist after verified Worker patch");
        }
    }

    @Test
    void deletesExistingThenMissingWithoutReusingIds() throws Exception {
        ReminderRepository repo = new InMemoryReminderRepository();
        Reminder first = repo.save("meet", LocalTime.NOON);
        Method deletion = ReminderRepository.class.getMethod("deleteById", long.class);
        assertThat(deletion.invoke(repo, first.id())).isEqualTo(true);
        assertThat(deletion.invoke(repo, first.id())).isEqualTo(false);
        assertThat(repo.save("later", LocalTime.NOON).id()).isEqualTo(first.id() + 1);
    }

    @Test
    void caseInsensitiveSearchFindsSavedText() throws Exception {
        ReminderRepository repo = new InMemoryReminderRepository();
        Reminder saved = repo.save("Drink Water", LocalTime.NOON);
        Method search = ReminderRepository.class.getMethod("findByTextContaining", String.class);
        @SuppressWarnings("unchecked")
        java.util.List<Reminder> found = (java.util.List<Reminder>) search.invoke(repo, "  WATER  ");
        assertThat(found).containsExactly(saved);
    }
}

package lf.sandbox.time.reminder;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;

import java.time.LocalTime;
import org.junit.jupiter.api.Test;

class ReminderRepositoryVisibleTest {

    @Test
    void idsStartAtOneAndIncrease() {
        ReminderRepository repository = new InMemoryReminderRepository();
        assertThat(repository.save("first", LocalTime.of(9, 0)).id()).isEqualTo(1L);
        assertThat(repository.save("second", LocalTime.of(10, 0)).id()).isEqualTo(2L);
    }

    @Test
    void stripsTextAndTruncatesSeconds() {
        ReminderRepository repository = new InMemoryReminderRepository();
        Reminder saved = repository.save("  drink water  ", LocalTime.of(14, 20, 30, 987_000_000));
        assertThat(saved.text()).isEqualTo("drink water");
        assertThat(saved.at()).isEqualTo(LocalTime.of(14, 20, 30));
    }

    @Test
    void findAllIsOrderedAndUnmodifiable() {
        ReminderRepository repository = new InMemoryReminderRepository();
        Reminder first = repository.save("one", LocalTime.NOON);
        Reminder second = repository.save("two", LocalTime.NOON);
        assertThat(repository.findAll()).extracting(Reminder::id).containsExactly(first.id(), second.id());
        assertThatThrownBy(() -> repository.findAll().clear())
                .isInstanceOf(UnsupportedOperationException.class);
    }

    @Test
    void blankTextRejectedWithoutSaving() {
        ReminderRepository repository = new InMemoryReminderRepository();
        assertThatThrownBy(() -> repository.save("   ", LocalTime.NOON))
                .isInstanceOf(IllegalArgumentException.class);
        assertThat(repository.findAll()).isEmpty();
    }
}
